mapper.select:
select distinct  from lab_hazard h
left join lab_device d on h.target_type='DEVICE' and d.id=h.target_id and d.del_flag='0'
where h.del_flag='0'
and (h.owner_id=#{viewerId}
or 1=1

    or ((h.target_type='LABORATORY' and h.target_id in #{id})
    or (h.target_type='DEVICE' and d.laboratory_id in #{id}))
)
and h.owner_id=#{ownerId}and h.status=#{status}and h.severity=#{severity}
order by h.create_time desc
